import{_ as t,a,o as i,a6 as r}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Attribute Families","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/catalog/families/index.md","filePath":"api/rest-api/admin/catalog/families/index.md","lastUpdated":1786429091000}'),o={name:"api/rest-api/admin/catalog/families/index.md"};function d(s,e,n,l,c,m){return i(),a("div",null,e[0]||(e[0]=[r('<h1 id="attribute-families" tabindex="-1">Attribute Families <a class="header-anchor" href="#attribute-families" aria-label="Permalink to &quot;Attribute Families&quot;">​</a></h1><p>An attribute family is the <strong>template of fields a product carries</strong>. Every product belongs to exactly one family, and the family decides which attributes (and in what layout) appear on that product&#39;s edit form. The Attribute Families menu lists, creates, edits, and deletes them. It mirrors the admin <strong>Catalog → Attribute Families</strong> screen.</p><h2 id="how-a-family-is-structured" tabindex="-1">How a family is structured <a class="header-anchor" href="#how-a-family-is-structured" aria-label="Permalink to &quot;How a family is structured&quot;">​</a></h2><p>A family is a set of <strong>attribute groups</strong>, and each group holds a list of <strong>attributes</strong>:</p><ul><li><strong>Groups</strong> (e.g. <code>General</code>, <code>Description</code>, <code>Meta Description</code>, <code>Price</code>, <code>Inventories</code>, <code>Images</code>) organise the edit form into sections. Each group has a <code>column</code> (1 or 2) controlling which side of the form it renders on, and a <code>position</code> (order).</li><li><strong>Attributes</strong> within a group are references to entries from the <a href="/api/rest-api/admin/catalog/attributes/">Attributes</a> menu, each with its own <code>position</code> and <code>isRequired</code> flag.</li></ul><p>The single-family endpoint returns the full <code>attributeGroups</code> array (each group with its nested <code>attributes</code>) inline; the listing is slim (id, code, name only) — fetch the structure by id.</p><h2 id="editing-the-structure" tabindex="-1">Editing the structure <a class="header-anchor" href="#editing-the-structure" aria-label="Permalink to &quot;Editing the structure&quot;">​</a></h2><p>Create and update accept the nested <code>attribute_groups</code> (with <code>custom_attributes</code>). On update, groups are matched by id; a group keyed <code>group_*</code> is created, and an existing group id omitted from the payload is removed (and so are omitted attributes within a kept group). This mirrors the admin form&#39;s add/remove behaviour.</p><h2 id="delete-guards" tabindex="-1">Delete guards <a class="header-anchor" href="#delete-guards" aria-label="Permalink to &quot;Delete guards&quot;">​</a></h2><p>A family <strong>cannot be deleted</strong> if it is the last remaining family, or if any product is still assigned to it — both return an error. Reassign or remove those products first.</p><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/catalog/families/families-listing.html">List families</a></td><td><code>GET /api/admin/catalog/families</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/families/families-detail.html">Family detail</a></td><td><code>GET /api/admin/catalog/families/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/families/families-create.html">Create family</a></td><td><code>POST /api/admin/catalog/families</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/families/families-update.html">Update family</a></td><td><code>PUT /api/admin/catalog/families/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/families/families-delete.html">Delete family</a></td><td><code>DELETE /api/admin/catalog/families/{id}</code></td></tr></tbody></table><p>All Attribute Families endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>. Reads require <code>catalog.families.view</code>; writes require the matching <code>catalog.families.create</code> / <code>.edit</code> / <code>.delete</code> permission.</p>',13)]))}const p=t(o,[["render",d]]);export{h as __pageData,p as default};
